import{_ as s,o as a,c as t,a2 as i}from"./chunks/framework.BEUshCVJ.js";const u=JSON.parse('{"title":"安装 MeetCue","description":"","frontmatter":{},"headers":[],"relativePath":"zh/install.md","filePath":"zh/install.md","lastUpdated":1793312058000}'),l={name:"zh/install.md"};function n(o,e,p,h,r,c){return a(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="安装-meetcue" tabindex="-1">安装 MeetCue <a class="header-anchor" href="#安装-meetcue" aria-label="Permalink to &quot;安装 MeetCue&quot;">​</a></h1><p>本页介绍如何在 Windows 和 macOS 上安装、升级和卸载 MeetCue。全程不需要管理员权限。</p><h2 id="系统要求" tabindex="-1">系统要求 <a class="header-anchor" href="#系统要求" aria-label="Permalink to &quot;系统要求&quot;">​</a></h2><ul><li>Windows 10 2004 及以上版本 / Windows 11（64 位），或 macOS 13 及以上版本（Apple 芯片或 Intel）。</li><li>Windows 上需要 Microsoft Edge WebView2 运行时。几乎所有 Windows 10 和 11 电脑都已预装。如果 MeetCue 提示 <a href="/meetcue/zh/troubleshooting/error-codes#mc-sys-001">MC-SYS-001</a>，请从微软官网安装 Evergreen 版运行时。</li><li>一个语音识别供应商的 API 密钥，和一个大模型供应商的 API 密钥。参见<a href="/meetcue/zh/guide/providers">供应商配置</a>。</li></ul><div class="info custom-block"><p class="custom-block-title">Linux</p><p>MeetCue 可以在 Linux 上编译运行，但尚未实现原生音频采集后端。</p></div><h2 id="在-macos-上安装" tabindex="-1">在 macOS 上安装 <a class="header-anchor" href="#在-macos-上安装" aria-label="Permalink to &quot;在 macOS 上安装&quot;">​</a></h2><p>需要 macOS 13 Ventura 或更高版本，支持 Apple 芯片和 Intel。从 <a href="https://github.com/Amazingkenneth/meetcue/releases" target="_blank" rel="noreferrer">Releases</a> 下载 <code>meetcue-macos-arm64.dmg</code>（Apple 芯片）或 <code>meetcue-macos-x64.dmg</code>（Intel），打开后把 <strong>MeetCue.app</strong> 拖到 <strong>应用程序</strong>。发布前也可从拉取请求的 CI 下载应用 ZIP 测试。</p><p>当前 Mac 安装包采用临时签名，尚未经 Apple 公证。如果 macOS 拦截了从本仓库下载的应用，请在 <strong>系统设置 › 隐私与安全性</strong> 中针对 MeetCue 选择 <strong>仍要打开</strong>，不要全局关闭 Gatekeeper。</p><p>首次使用时，在 <strong>系统设置 › 隐私与安全性</strong> 中允许 <strong>麦克风</strong> 和 <strong>屏幕与系统音频录制</strong>（旧版系统为 <strong>屏幕录制</strong>）。授权后退出并重新打开 MeetCue。系统声音通过 ScreenCaptureKit 获取，不录制屏幕图像，也不需要虚拟声卡驱动。未在 设置 › 音频 中指定麦克风时，会跟随系统默认输入设备。</p><p>无需密钥即可体验：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/Applications/MeetCue.app/Contents/MacOS/MeetCue</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --demo</span></span></code></pre></div><p>同一可执行文件加 <code>--self-test</code> 可检查音频和快捷键。请连接耳机，并在麦克风测试期间说话。API 密钥保存在 macOS 钥匙串中。更新时替换应用程序目录中的应用，会保留设置和密钥。要一并清除它们，先使用 <strong>设置 › 通用 › 清除全部数据</strong>，再删除应用。</p><h2 id="用-scoop-安装" tabindex="-1">用 Scoop 安装 <a class="header-anchor" href="#用-scoop-安装" aria-label="Permalink to &quot;用 Scoop 安装&quot;">​</a></h2><ol><li><p>如果还没有安装 Scoop，打开 PowerShell 并运行：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Set-ExecutionPolicy</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ExecutionPolicy RemoteSigned </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Scope CurrentUser</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">irm get.scoop.sh </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> iex</span></span></code></pre></div></li><li><p>添加 MeetCue 的 bucket：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">scoop bucket add meetcue https:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">//</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">github.com</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Amazingkenneth</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">meetcue</span></span></code></pre></div></li><li><p>安装 MeetCue：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">scoop install meetcue</span></span></code></pre></div></li><li><p>从开始菜单启动 <strong>MeetCue</strong>。首次运行会打开设置向导，请继续阅读<a href="/meetcue/zh/setup">首次设置</a>。</p></li></ol><h2 id="升级" tabindex="-1">升级 <a class="header-anchor" href="#升级" aria-label="Permalink to &quot;升级&quot;">​</a></h2><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">scoop update meetcue</span></span></code></pre></div><p>设置、延迟探测历史和练习记录保存在 Scoop 的 <code>persist</code> 目录中，API 密钥保存在 Windows 凭据管理器中，因此升级后都会保留。</p><h2 id="卸载" tabindex="-1">卸载 <a class="header-anchor" href="#卸载" aria-label="Permalink to &quot;卸载&quot;">​</a></h2><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">scoop uninstall meetcue</span></span></code></pre></div><p>如果要同时删除设置，加上 <code>--purge</code>。API 密钥保留在 Windows 凭据管理器中名为 <code>MeetCue</code> 的条目里，如有需要请在那里删除；也可以在卸载前运行 <strong>设置 › 通用 › 清除所有数据</strong>，一并删除密钥和设置。</p><h2 id="遇到问题" tabindex="-1">遇到问题 <a class="header-anchor" href="#遇到问题" aria-label="Permalink to &quot;遇到问题&quot;">​</a></h2><p>请参阅<a href="/meetcue/zh/troubleshooting/install">安装与升级排错</a>。</p>`,22)])])}const k=s(l,[["render",n]]);export{u as __pageData,k as default};
